// Registro de tipografías Roma Fitness para jsPDF. Generado a partir de los archivos incluidos en /fuentes.
function registrarFuentesRoma(pdf) {
  pdf.addFileToVFS("BarlowCondensed-Regular.ttf", "");
  pdf.addFont("BarlowCondensed-Regular.ttf", "BarlowCondensedRegular", "normal");
  pdf.addFileToVFS("BarlowCondensed-Medium.ttf", "");
  pdf.addFont("BarlowCondensed-Medium.ttf", "BarlowCondensedMedium", "normal");
  pdf.addFileToVFS("BebasNeue-Regular.ttf", "");
  pdf.addFont("BebasNeue-Regular.ttf", "BebasNeue", "normal");
}
